const a="https://nominatim.openstreetmap.org/search",s=async t=>{if(!t)return null;try{const r=await fetch(`${a}?format=json&q=${encodeURIComponent(t)}&limit=1`);if(!r.ok)throw new Error("Geocoding request failed");const o=await r.json();if(Array.isArray(o)&&o.length>0&&o[0].lat&&o[0].lon){const n=parseFloat(o[0].lat),e=parseFloat(o[0].lon);if(!isNaN(n)&&!isNaN(e))return{lat:n,lng:e}}return null}catch(r){return console.error("Geocoding error:",r),null}};export{s as geocodeAddress};
